import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        double numerator = 0;
        double denominator = 1;

        for (int i = 1; i <= n; i++) {
            double ratio = x / y;
            double floor_val = Math.floor(ratio * i);
            long ceil_val = (long) Math.ceil(ratio * i);

            if (Math.abs(ratio - floor_val / i) < Math.abs(ratio - numerator / denominator)) {
                numerator = floor_val;
                denominator = i;
            }
            if (Math.abs(ratio - (double)ceil_val / i) < Math.abs(ratio - numerator / denominator)) {
                numerator = ceil_val;
                denominator = i;
            }
        }
        System.out.println((long)numerator + "/" + (long)denominator);
    }
}
